const test=require('node:test'),assert=require('node:assert/strict'),lib=import('../board-join-verifier.js');
const board={id:'board',revision:2};const candidate=(a={x:0,y:0,z:0},b={x:4,y:0,z:0})=>({signature:'current',access:{a,b}});
const config=()=>({boardId:board.id,boardRevision:board.revision,heightAt:()=>0,contains:()=>true,obstaclesComplete:true});
test('real corridor evidence includes sampled terrain and rejects incomplete or stale geometry',async()=>{const {createJoinVerifier}=await lib,verify=createJoinVerifier(config()),result=verify(candidate(),board);assert.equal(result.traversable,true);assert.equal(result.path.length,9);assert.equal(createJoinVerifier({...config(),obstaclesComplete:false})(candidate(),board),null);assert.equal(verify(candidate(),{...board,revision:3}),null);});
test('thin and rotated obstacles cannot fall between terrain samples',async()=>{const {createJoinVerifier}=await lib;for(const o of [{kind:'box',x:2.17,z:0,w:.01,d:3,angle:0},{kind:'box',x:2,z:0,w:3,d:.01,angle:.8},{kind:'circle',x:2.17,z:.55,radius:.05}])assert.equal(createJoinVerifier({...config(),obstacles:[o]})(candidate(),board),null);assert(createJoinVerifier({...config(),obstacles:[{kind:'circle',x:2,z:2,radius:.2}]})(candidate(),board));});
test('steep ground, narrow cross-slopes, missing terrain and out-of-bounds corridors reject',async()=>{const {createJoinVerifier}=await lib;for(const override of [{heightAt:x=>x*.5},{heightAt:()=>NaN},{heightAt:(x,z)=>z},{contains:(x,z)=>z>=0},{heightAt:()=>.2}])assert.equal(createJoinVerifier({...config(),...override})(candidate(),board),null);});
test('assembly fence geometry preserves actual gate opening and rejects crossing rails',async()=>{const {createJoinVerifier,assemblyObstacles}=await lib,obstacles=assemblyObstacles({plans:[{center:{x:0,z:0},placements:[{role:'enclosure',x:0,z:-5,w:10,d:10,angle:0}]}]});const verify=createJoinVerifier({...config(),obstacles});assert(verify(candidate({x:0,y:0,z:1},{x:0,y:0,z:-1}),board));assert.equal(verify(candidate({x:3,y:0,z:1},{x:3,y:0,z:-1}),board),null);});
